async def read_groups():
    async with Engine(caching=True):
        with open('groups_ids.txt', 'r') as f:
            ids = list(map(int, f.read().split(',')))
            for batch in tqdm(batcher(ids, 100), total=int(len(ids) / 100)):
                data = await VKGroups(batch).data()
                for group in data:
                    if not group or not group.get('name') or isinstance(group, Exception):
                        continue
                    # print(group)
                    description = group.get('description', '')
                    name = group.get('name', '')
                    text = f'{name} {description}'.lower()
                    keywords = ['mipt', 'phystech', 'fpmi', 'физтех', 'мфти',
                                'фопф', 'фупм', 'институт', 'institute', 'university', 'универ', 'физ']
                    for word in keywords:
                        if word in text:
                            target_ids.add(group['id'])
                            break
    print()
    print()
    print(target_ids)


