def append_users(ids):
    with open('mipt_students4.txt', 'a') as f:
        f.write('\n'.join(map(str, ids)) + '\n')


async def get_groups_members(mipt_groups):
    async with Engine(caching=True):
        for group_id in tqdm(mipt_groups):
            try:
                group = await VKGroup.create(group_id)
                members = await group.members(all_=True)
                append_users(members.nodes)
            except:
                print('error')


async def main():
    async with Engine(caching=True):
        start_group = 'https://vk.com/miptru'
        group = await VKGroup.create(start_group)
        print(await group.name())
        members = await group.members(count=1000)
        groups = await members.groups()
        # data = await groups.data()
        with open('groups_ids.txt', 'w') as f:
            f.write(str(','.join(map(str, groups.nodes))))
        # groups = await members.groups()
        # print(len(groups))

unique_ids = set()


def unique_students():
    with open('mipt_students4.txt', 'r') as f:
        ids = f.read().split('\n')
        with open('mipt_students4_unique.txt', 'w') as f:
            f.write('\n'.join(map(str, set(ids))))


async def get_images(user_id):
    data = await VKUser(user_id).profile_photos(count=1000)
    urls = []
    for item in await data.data():
        urls.append(item['sizes'][-1]['url'])
    print(urls)
    return urls


def save_urls(user_id, urls):
    with open('user_photos2.txt', 'a') as f:
        f.write(f'{user_id}\t' + ','.join(urls) + '\n')


async def save_image_urls():
    async with Engine(caching=True):
        num_lines = sum(1 for line in open('mipt_students4_unique.txt', 'r'))
        with open('mipt_students4_unique.txt', 'r') as f:
            for line in tqdm(f, total=num_lines):
                try:
                    id_ = int(line)
                    urls = await get_images(id_)
                    save_urls(id_, urls)
                except:
                    print('Error')

